import { useMemo, useState } from "react";

export type StreamEvent = {
  id: string;
  level: "info" | "warn" | "error";
  source: string;
  message: string;
  at: number;
};

const LEVELS = ["info", "warn", "error"] as const;

export function ActivityStreamLive({
  events,
  unseenFrom = 0,
}: {
  events: StreamEvent[];
  unseenFrom?: number;
}) {
  const [levels, setLevels] = useState<string[]>([...LEVELS]);

  const visible = useMemo(
    () => events.filter((e) => levels.includes(e.level)),
    [events, levels],
  );

  const toggle = (level: string) =>
    setLevels((prev) =>
      prev.includes(level) ? prev.filter((l) => l !== level) : [...prev, level],
    );

  const ago = (at: number) => {
    const seconds = Math.max(0, Math.round((Date.now() - at) / 1000));
    if (seconds < 60) return seconds + "s ago";
    if (seconds < 3600) return Math.round(seconds / 60) + "m ago";
    return Math.round(seconds / 3600) + "h ago";
  };

  return (
    <div className="asl-root">
      <header className="asl-filter">
        {LEVELS.map((level) => (
          <button
            key={level}
            type="button"
            aria-pressed={levels.includes(level)}
            onClick={() => toggle(level)}
            className="asl-chip"
            data-level={level}
          >
            {level}
          </button>
        ))}
      </header>

      <ol className="asl-list">
        {visible.map((event, index) => (
          <li key={event.id}>
            {index === unseenFrom ? (
              <div className="asl-divider" role="separator">
                new events
              </div>
            ) : null}
            <article className="asl-event" data-level={event.level}>
              <span className="asl-level" aria-hidden="true" />
              <span className="asl-source">{event.source}</span>
              <p className="asl-message">{event.message}</p>
              <time className="asl-time" dateTime={new Date(event.at).toISOString()}>
                {ago(event.at)}
              </time>
            </article>
          </li>
        ))}
      </ol>
    </div>
  );
}

