.asl-root {
  display: flex;
  flex-direction: column;
  max-height: 520px;
  background: var(--surface-inset, #0c0e13);
  border: 1px solid var(--line-subtle, #1e2230);
  border-radius: 10px;
  overflow: hidden;
  font-size: 12px;
  color: var(--text-strong, #e2e8f0);
  --level-info: #38bdf8;
  --level-warn: #fbbf24;
  --level-error: #f87171;
}
.asl-filter {
  display: flex;
  gap: 6px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-subtle, #1e2230);
}
.asl-chip {
  padding: 2px 9px;
  font: inherit;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border-radius: 999px;
  border: 1px solid var(--line-strong, #334155);
  background: transparent;
  color: var(--text-muted, #94a3b8);
  cursor: pointer;
}
.asl-chip[aria-pressed="true"] {
  color: var(--text-strong, #ffffff);
  border-color: currentColor;
}
.asl-chip[data-level="error"][aria-pressed="true"] { color: var(--level-error); }
.asl-chip[data-level="warn"][aria-pressed="true"] { color: var(--level-warn); }
.asl-chip[data-level="info"][aria-pressed="true"] { color: var(--level-info); }
.asl-list {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
}
.asl-divider {
  position: sticky;
  top: 0;
  padding: 3px 10px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  background: var(--accent, #6366f1);
  color: #ffffff;
}
.asl-event {
  display: grid;
  grid-template-columns: 6px 78px 1fr auto;
  align-items: baseline;
  gap: 10px;
  padding: 7px 12px;
  border-bottom: 1px solid var(--line-subtle, #171c26);
}
.asl-event:hover {
  background: rgba(255, 255, 255, 0.03);
}
.asl-level {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--level-info);
}
.asl-event[data-level='warn'] .asl-level { background: var(--level-warn); }
.asl-event[data-level='error'] .asl-level { background: var(--level-error); }
.asl-source {
  font-family: ui-monospace, monospace;
  font-size: 11px;
  color: var(--text-muted, #94a3b8);
  overflow: hidden;
  text-overflow: ellipsis;
}
.asl-message {
  margin: 0;
  line-height: 1.5;
  word-break: break-word;
}
.asl-time {
  font-size: 10px;
  color: var(--text-muted, #64748b);
  white-space: nowrap;
}
